/* eslint-disable @next/next/no-img-element -- WebP variants are pre-generated by the
   media pipeline and served from /api/media; next/image would add no value here. */
"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";

/**
 * Client-side limits. The server (src/lib/content/media.ts) is the authoritative
 * source — it is NOT imported here on purpose: it pulls in `sharp` and `node:fs`,
 * which would break the client bundle. These values must stay in sync with it.
 */
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp"];
const MAX_IMAGE_BYTES = 10 * 1024 * 1024; // 10 MB

const ERROR_MESSAGES: Record<string, string> = {
  INVALID_FORMAT: "Непідтримуваний формат файлу",
  IMAGE_TOO_LARGE: "Зображення занадто велике (максимум 10 МБ)",
  INVALID_FILE: "Файл не передано",
};
const DEFAULT_ERROR_MESSAGE = "Сталася помилка сервера";

type UploadStatus = "uploading" | "done" | "error";

type UploadItem = {
  uid: string;
  name: string;
  sizeBytes: number;
  progress: number;
  status: UploadStatus;
  errorCode?: string;
  assetId?: string;
};

type LibraryItem = {
  id: string;
  originalName: string;
};

type Props = {
  open: boolean;
  onClose: () => void;
  onSelect: (assetIds: string[]) => void;
};

const FOCUSABLE_SELECTOR =
  'button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [href], [tabindex]:not([tabindex="-1"])';

function formatBytes(bytes: number): string {
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(1)} КБ`;
  return `${(kb / 1024).toFixed(1)} МБ`;
}

export function ImageUploadDialog({ open, onClose, onSelect }: Props) {
  const titleId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const lastActiveElement = useRef<HTMLElement | null>(null);
  const pendingFiles = useRef<Map<string, File>>(new Map());

  const [tab, setTab] = useState<"upload" | "library">("upload");
  const [uploads, setUploads] = useState<UploadItem[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [dragOver, setDragOver] = useState(false);

  const [libraryItems, setLibraryItems] = useState<LibraryItem[]>([]);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [loadingMore, setLoadingMore] = useState(false);
  const libraryFetchStarted = useRef(false);

  // Every close path (Cancel / Escape / Додати) funnels through here, so the
  // dialog always reopens with a fresh selection and an empty upload list.
  const resetState = useCallback(() => {
    setTab("upload");
    setUploads([]);
    setSelectedIds([]);
    setDragOver(false);
    setLibraryItems([]);
    setNextCursor(null);
    setLoadingMore(false);
    libraryFetchStarted.current = false;
    pendingFiles.current.clear();
  }, []);

  const close = useCallback(() => {
    resetState();
    onClose();
  }, [resetState, onClose]);

  // Focus management: remember the previously active element, focus the first
  // focusable control on open, restore focus on close.
  useEffect(() => {
    if (!open) return;
    lastActiveElement.current = document.activeElement as HTMLElement | null;
    const first = dialogRef.current?.querySelector<HTMLElement>(FOCUSABLE_SELECTOR);
    first?.focus();
    return () => {
      lastActiveElement.current?.focus();
    };
  }, [open]);

  const markSelected = useCallback((assetId: string) => {
    setSelectedIds((prev) => (prev.includes(assetId) ? prev : [...prev, assetId]));
  }, []);

  const toggleUploadSelection = useCallback((item: UploadItem) => {
    if (item.status !== "done" || !item.assetId) return;
    const assetId = item.assetId;
    setSelectedIds((prev) => (prev.includes(assetId) ? prev.filter((id) => id !== assetId) : [...prev, assetId]));
  }, []);

  const startUpload = useCallback(
    (uid: string, file: File) => {
      pendingFiles.current.set(uid, file);
      const formData = new FormData();
      formData.append("file", file);

      const xhr = new XMLHttpRequest();
      xhr.open("POST", "/api/admin/media");

      xhr.upload.onprogress = (event) => {
        if (!event.total) return;
        const progress = Math.round((event.loaded / event.total) * 100);
        setUploads((prev) => prev.map((item) => (item.uid === uid ? { ...item, progress } : item)));
      };

      const finish = (status: UploadStatus, errorCode?: string, assetId?: string) => {
        setUploads((prev) =>
          prev.map((item) =>
            item.uid === uid ? { ...item, status, errorCode, assetId, progress: status === "done" ? 100 : item.progress } : item
          )
        );
      };

      xhr.onload = () => {
        if (xhr.status === 200 || xhr.status === 201) {
          try {
            const data = JSON.parse(xhr.responseText) as { id?: string };
            if (typeof data.id === "string") {
              finish("done", undefined, data.id);
              markSelected(data.id);
              return;
            }
          } catch {
            // fall through to the error path
          }
          finish("error", "INTERNAL_ERROR");
        } else {
          let code = "INTERNAL_ERROR";
          try {
            const data = JSON.parse(xhr.responseText) as { error?: string };
            if (typeof data.error === "string") code = data.error;
          } catch {
            // keep INTERNAL_ERROR
          }
          finish("error", code);
        }
      };
      xhr.onerror = () => finish("error", "INTERNAL_ERROR");
      xhr.send(formData);
    },
    [markSelected]
  );

  const addFiles = useCallback(
    (files: FileList | null) => {
      if (!files) return;
      const list = Array.from(files);
      for (const file of list) {
        const uid = crypto.randomUUID();
        if (!ALLOWED_IMAGE_TYPES.includes(file.type)) {
          setUploads((prev) => [
            ...prev,
            { uid, name: file.name, sizeBytes: file.size, progress: 0, status: "error", errorCode: "INVALID_FORMAT" }
          ]);
          continue;
        }
        if (file.size > MAX_IMAGE_BYTES) {
          setUploads((prev) => [
            ...prev,
            { uid, name: file.name, sizeBytes: file.size, progress: 0, status: "error", errorCode: "IMAGE_TOO_LARGE" }
          ]);
          continue;
        }
        setUploads((prev) => [...prev, { uid, name: file.name, sizeBytes: file.size, progress: 0, status: "uploading" }]);
        startUpload(uid, file);
      }
    },
    [startUpload]
  );

  const retryUpload = useCallback(
    (uid: string) => {
      const file = pendingFiles.current.get(uid);
      if (!file) return;
      setUploads((prev) =>
        prev.map((item) => (item.uid === uid ? { ...item, status: "uploading", progress: 0, errorCode: undefined } : item))
      );
      startUpload(uid, file);
    },
    [startUpload]
  );

  const loadLibraryPage = useCallback(async (cursor: string | null) => {
    const url = cursor ? `/api/admin/media?cursor=${encodeURIComponent(cursor)}` : "/api/admin/media";
    const res = await fetch(url);
    if (!res.ok) return;
    const data = (await res.json()) as { items: LibraryItem[]; nextCursor: string | null };
    setLibraryItems((prev) => (cursor ? [...prev, ...data.items] : data.items));
    setNextCursor(data.nextCursor);
  }, []);

  // First open of the library tab triggers the initial fetch.
  useEffect(() => {
    if (!open || tab !== "library" || libraryFetchStarted.current) return;
    libraryFetchStarted.current = true;
    loadLibraryPage(null);
  }, [open, tab, loadLibraryPage]);

  const loadMore = useCallback(async () => {
    if (!nextCursor || loadingMore) return;
    setLoadingMore(true);
    try {
      await loadLibraryPage(nextCursor);
    } finally {
      setLoadingMore(false);
    }
  }, [nextCursor, loadingMore, loadLibraryPage]);

  const toggleLibraryItem = useCallback((id: string) => {
    setSelectedIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  }, []);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Escape") {
        close();
        return;
      }
      if (event.key !== "Tab") return;
      const root = dialogRef.current;
      if (!root) return;
      const focusables = Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));
      if (focusables.length === 0) return;
      event.preventDefault();
      const index = focusables.indexOf(document.activeElement as HTMLElement);
      if (event.shiftKey) {
        const next = index <= 0 ? focusables.length - 1 : index - 1;
        focusables[next].focus();
      } else {
        const next = index === -1 || index === focusables.length - 1 ? 0 : index + 1;
        focusables[next].focus();
      }
    },
    [close]
  );

  if (!open) return null;

  return createPortal(
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onKeyDown={handleKeyDown}
        className="w-full max-w-2xl rounded-2xl bg-gray-900 border border-gray-800 p-6 shadow-2xl space-y-4 max-h-[85vh] flex flex-col"
      >
        <h2 id={titleId} className="text-lg font-semibold text-white">
          Вибір зображень
        </h2>

        <div className="flex gap-4 border-b border-gray-800">
          <button
            type="button"
            onClick={() => setTab("upload")}
            className={`pb-2 -mb-px border-b-2 text-sm font-medium transition-colors ${
              tab === "upload" ? "border-indigo-500 text-white" : "border-transparent text-gray-400 hover:text-gray-300"
            }`}
          >
            Завантажити
          </button>
          <button
            type="button"
            onClick={() => setTab("library")}
            className={`pb-2 -mb-px border-b-2 text-sm font-medium transition-colors ${
              tab === "library" ? "border-indigo-500 text-white" : "border-transparent text-gray-400 hover:text-gray-300"
            }`}
          >
            Медіатека
          </button>
        </div>

        {tab === "upload" ? (
          <div className="space-y-3 overflow-y-auto">
            <div
              onDragOver={(event) => {
                event.preventDefault();
                setDragOver(true);
              }}
              onDragLeave={() => setDragOver(false)}
              onDrop={(event) => {
                event.preventDefault();
                setDragOver(false);
                addFiles(event.dataTransfer.files);
              }}
              className={`rounded-xl border-2 border-dashed p-4 text-center ${
                dragOver ? "border-indigo-500 bg-indigo-500/10" : "border-gray-700"
              }`}
            >
              <p className="text-sm text-gray-400 mb-3">Перетягніть зображення сюди (JPEG, PNG, WebP, до 10 МБ)</p>
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium rounded-lg transition-colors"
              >
                Вибрати файли
              </button>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept="image/jpeg,image/png,image/webp"
                tabIndex={-1}
                className="hidden"
                onChange={(event) => {
                  addFiles(event.target.files);
                  event.target.value = "";
                }}
              />
            </div>

            {uploads.length > 0 && (
              <ul className="space-y-2">
                {uploads.map((item) => {
                  const selected = item.status === "done" && item.assetId != null && selectedIds.includes(item.assetId);
                  const message =
                    item.status === "error" ? (ERROR_MESSAGES[item.errorCode ?? ""] ?? DEFAULT_ERROR_MESSAGE) : null;
                  return (
                    <li key={item.uid}>
                      <div
                        role="button"
                        tabIndex={0}
                        aria-pressed={selected}
                        onClick={() => toggleUploadSelection(item)}
                        className={`w-full text-left rounded-lg border px-3 py-2 transition-colors ${
                          item.status === "error"
                            ? "border-red-900 bg-red-950/30"
                            : selected
                              ? "border-indigo-500 bg-indigo-500/10"
                              : "border-gray-800 bg-gray-800/40 hover:bg-gray-800/70"
                        }`}
                      >
                        <div className="flex items-center gap-2 text-sm">
                          {item.status === "done" ? (
                            <span className="text-green-400" aria-hidden>
                              ✓
                            </span>
                          ) : item.status === "error" ? (
                            <span className="text-red-400" aria-hidden>
                              ✕
                            </span>
                          ) : (
                            <span className="text-gray-500" aria-hidden>
                              …
                            </span>
                          )}
                          <span className="truncate text-gray-200 flex-1">{item.name}</span>
                          <span className="text-gray-500 text-xs shrink-0">{formatBytes(item.sizeBytes)}</span>
                          <span className="text-xs text-gray-400 shrink-0" aria-hidden>
                            {selected ? "☑" : "☐"}
                          </span>
                        </div>
                        {item.status === "uploading" && (
                          <div className="mt-2 h-1.5 rounded-full bg-gray-700 overflow-hidden">
                            <div
                              className="h-full bg-indigo-500 transition-[width]"
                              style={{ width: `${item.progress}%` }}
                            />
                          </div>
                        )}
                        {message && <p className="mt-1 text-xs text-red-400">{message}</p>}
                        {item.status === "error" && (
                          <button
                            type="button"
                            onClick={(event) => {
                              event.stopPropagation();
                              retryUpload(item.uid);
                            }}
                            className="mt-1 text-xs text-indigo-400 hover:text-indigo-300"
                          >
                            Повторити
                          </button>
                        )}
                      </div>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        ) : (
          <div className="overflow-y-auto space-y-3">
            {libraryItems.length === 0 ? (
              <p className="text-gray-500 text-center py-8">Медіатека порожня</p>
            ) : (
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                {libraryItems.map((item) => {
                  const selected = selectedIds.includes(item.id);
                  return (
                    <button
                      key={item.id}
                      type="button"
                      onClick={() => toggleLibraryItem(item.id)}
                      title={item.originalName}
                      className={selected ? "ring-2 ring-indigo-500 rounded-lg" : "ring-0 rounded-lg"}
                    >
                      <img
                        src={`/api/media/${item.id}/480`}
                        alt={item.originalName}
                        className="aspect-square object-cover rounded-lg"
                      />
                    </button>
                  );
                })}
              </div>
            )}
            {nextCursor && (
              <div className="text-center">
                <button
                  type="button"
                  onClick={loadMore}
                  disabled={loadingMore}
                  className="px-4 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
                >
                  {loadingMore ? "Завантаження…" : "Завантажити ще"}
                </button>
              </div>
            )}
          </div>
        )}

        <div className="flex justify-end gap-2 pt-2">
          <button
            type="button"
            onClick={close}
            className="px-4 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-sm font-medium rounded-lg transition-colors"
          >
            Скасувати
          </button>
          <button
            type="button"
            disabled={selectedIds.length === 0}
            onClick={() => {
              onSelect(selectedIds);
              close();
            }}
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
          >
            Додати ({selectedIds.length})
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}
